<style>
.fp .fp-department-heading{align-items:flex-start;margin-bottom:18px}.fp .fp-department-heading h2{margin:5px 0 0;font-size:21px}.fp-plan-list{padding:0;margin:0;list-style:none;display:grid;gap:10px}.fp-plan-item{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:16px 18px;border:1px solid #e0e8e2;border-radius:10px;background:#fafcfb}.fp-plan-description{min-width:0}.fp .fp-plan-name{font-size:15px;font-weight:650;color:#194b38;text-decoration:none;overflow-wrap:anywhere}.fp-plan-name:hover{text-decoration:underline}.fp-plan-meta{display:flex;flex-wrap:wrap;gap:6px 20px;margin-top:7px;font-size:12px;color:#687b70}.fp-plan-controls{display:flex;align-items:flex-start;gap:6px;flex:none}.fp-plan-controls>form{margin:0}.fp-plan-controls .fp-icon-btn{width:34px;height:34px;padding:7px;box-sizing:border-box}.fp-plan-controls summary{list-style:none}.fp-plan-controls summary::-webkit-details-marker{display:none}.fp-plan-settings{display:grid;gap:14px;margin-top:15px;max-width:520px}.fp-plan-edit[open]{width:min(480px,48vw)}.fp-plan-empty{font-size:13px;color:#687b70;padding:16px 0}.fp-new-plan[open]{width:min(520px,100%)}.fp-new-plan>summary{list-style:none}.fp-new-plan>summary::-webkit-details-marker{display:none}@media(max-width:650px){.fp-plan-item{flex-wrap:wrap;padding:13px}.fp-plan-controls{width:100%}.fp-plan-edit[open]{width:calc(100% - 40px)}.fp-plan-meta{flex-direction:column}}
.fp-offer-schedule{margin:20px 0;padding:16px;border:1px solid #dce6df;border-radius:10px}.fp-payment-row{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:12px;align-items:end;margin-bottom:12px}.fp-payment-row>.fp-btn{height:42px}.fp-offer-schedule>.fp-actions{justify-content:flex-start}@media(max-width:650px){.fp-payment-row{grid-template-columns:1fr 1fr}}
.fp .fp-kpi-grid{grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px}.fp .fp-kpi-grid>.fp-card{display:grid;grid-template-rows:32px auto 18px;padding:14px;margin:10px 0}.fp .fp-kpi-grid .fp-metric-title{min-height:32px;font-size:10px;line-height:15px;letter-spacing:.02em}.fp .fp-kpi-grid .fp-kpi{font-size:21px;padding-top:6px}.fp .fp-line-actions{display:flex;align-items:center;gap:3px;flex-wrap:nowrap}.fp .fp-line-actions form{margin:0}.fp .fp-line-actions .fp-icon-btn{display:inline-flex;padding:4px;width:24px;height:28px;box-sizing:border-box}.fp .fp-line-disabled{background:#f2f3f2}.fp .fp-line-disabled .fp-source-name{color:#758078}@media(max-width:650px){.fp .fp-kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
.fp [hidden]{display:none!important}
.fp{--fp-green:#1a4d3a;max-width:1600px;margin:auto;color:#25372e}.fp h1{font-size:27px;margin:0 0 6px}.fp h2{font-size:19px;margin:0 0 16px}.fp h3{font-size:16px;margin:0 0 12px}.fp p{line-height:1.6}.fp-muted{color:#687b70;font-size:13px}.fp-head,.fp-actions{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.fp-head{margin-bottom:22px}.fp-card{background:#fff;border:1px solid #dce6df;border-radius:14px;padding:22px;margin:18px 0;box-shadow:0 4px 18px #173f2b05}.fp-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.fp label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:600}.fp input,.fp select,.fp textarea{box-sizing:border-box;width:100%;padding:10px 12px;border:1px solid #ccd9d0;border-radius:8px;background:white;color:#25372e;font:inherit}.fp input[type=checkbox]{width:17px;height:17px}.fp .fp-check{flex-direction:row;align-items:center;font-weight:400}.fp fieldset{border:0;padding:0;margin:18px 0}.fp legend{font-weight:700;margin-bottom:12px}.fp-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #cddbd2;background:white;color:var(--fp-green);border-radius:8px;padding:10px 15px;font:inherit;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.fp-btn.primary{background:var(--fp-green);color:white;border-color:var(--fp-green)}.fp-btn.danger{color:#a22d2d}.fp-note{padding:13px 16px;background:#eef5f0;border-radius:8px;font-size:13px;margin:14px 0}.fp-warning{background:#fff8e8;color:#805317}.fp-error{background:#fff0ee;color:#9b2828}.fp-scroll{overflow-x:auto}.fp table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}.fp th,.fp td{text-align:left;padding:12px;border-bottom:1px solid #e3ebe6}.fp th{background:#f3f7f4;color:#4b6455;font-weight:600}.fp td.number{text-align:right;font-variant-numeric:tabular-nums}.fp tr.total-row{font-weight:700;background:#edf5ef}.fp .negative{color:#b23a32}.fp-badge{display:inline-block;background:#edf5ef;color:#285840;border-radius:20px;padding:4px 10px;font-size:12px}.fp-badge.warn{background:#fff3d8;color:#805317}.fp-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.fp-tabs a{padding:9px 16px;border:1px solid #d5e0d8;border-radius:20px;color:#476151;text-decoration:none;font-size:13px}.fp-tabs a.active{background:#1a4d3a;color:#fff}.fp summary{cursor:pointer;font-weight:600}.fp .fp-kpi{font-size:25px;font-weight:700;margin-top:10px}.fp small{font-weight:400;line-height:1.5}.fp .fp-wide{grid-column:1/-1}.fp details+details{margin-top:10px}.fp .fp-line-note{white-space:normal;min-width:180px;max-width:350px;font-size:12px;color:#7b6332}.fp .fp-check-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;max-height:220px;overflow:auto;margin:12px 0}.fp .fp-metric-title{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#698070}@media(max-width:650px){.fp-card{padding:15px}.fp h1{font-size:23px}.fp-grid{grid-template-columns:1fr}}
</style>
<style>
#line-form .fp-grid,#fp-account-form .fp-grid{align-items:start}#line-form label,#fp-account-form label{gap:6px;min-width:0}#line-form .fp-field-title,#fp-account-form .fp-field-title{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;min-height:36px;line-height:18px;font-size:12px}#line-form .fp-field-title>span:first-child,#fp-account-form .fp-field-title>span:first-child{flex:1;min-width:0}#line-form .fp-field-title .fp-info,#fp-account-form .fp-field-title .fp-info{flex:none;margin-left:0}#line-form input,#line-form select,#fp-account-form input,#fp-account-form select{height:42px;min-width:0}#line-form textarea{min-height:92px}#fp-account-form .fp-account-form-grid{align-items:end}#fp-account-form .fp-account-form-grid>.fp-btn,#fp-account-form .fp-account-form-grid>div>.fp-btn{min-height:42px}.fp-form-help{margin:14px 0;font-size:12px}.fp-grid>.fp-card{display:flex;flex-direction:column}.fp-grid>.fp-card .fp-metric-title{min-height:36px;line-height:18px}.fp-grid>.fp-card .fp-kpi{margin-top:auto;padding-top:12px}.fp-trend-title .fp-info,.fp h2 .fp-info,.fp h3 .fp-info{vertical-align:middle}.fp-chart-panel>summary{min-height:34px;box-sizing:border-box}.fp-chart-grid{align-items:start}
