<style>
.fp-chart-grid>.fp-chart-panel{align-self:start}.fp-chart-panel>summary{padding:0 8px 12px;font-size:15px}.fp-chart-panel:not([open])>summary{padding-bottom:8px}.fp-trend-summary{display:flex;align-items:center;justify-content:space-between;gap:20px;list-style:none}.fp-trend-summary::-webkit-details-marker{display:none}.fp-trend-summary:before{content:'▸';flex:none;color:#4f735c}.fp-trend-chart[open]>.fp-trend-summary:before{content:'▾'}.fp-trend-summary>span{flex:1;min-width:0}.fp-trend-summary .fp-muted{display:block;margin-top:6px;font-weight:400;font-size:12px}.fp-trend-title{display:block;font-size:19px;font-weight:700}.fp-trend-summary strong{text-align:right;font-size:21px;white-space:nowrap}.fp-trend-summary strong small{font-size:11px;white-space:normal;max-width:220px}.fp-trend-body{margin-top:18px}.fp-trend-body>details{margin-top:16px}.fp-account-form-grid{align-items:end;margin-top:18px}.fp-form-divider{border:0;border-top:1px solid #dce6df;margin:24px 0}.fp .fp-payment-description{white-space:normal;min-width:150px;max-width:320px;overflow-wrap:anywhere}@media(max-width:650px){.fp-trend-summary{flex-wrap:wrap;gap:12px}.fp-trend-summary strong{font-size:18px}.fp-trend-title{font-size:17px}}
