<style>
.fp-hint{display:inline-flex;vertical-align:middle}.fp-hint-trigger{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:help;text-align:inherit}.fp-value-hint{text-decoration:underline;text-decoration-style:dotted;text-decoration-color:#a7baae;text-underline-offset:4px;white-space:nowrap}.fp-info{display:inline-flex;align-items:center;justify-content:center;width:19px;height:19px;border:1px solid #b8cdbf;border-radius:50%;font-size:11px;font-weight:700;color:#37644c;margin-left:5px}.fp-hint-trigger:focus-visible,.fp-chart-panel g:focus-visible{outline:2px solid #337d5a;outline-offset:3px}.fp-tooltip{position:fixed;inset:auto;margin:0;box-sizing:border-box;width:max-content;max-width:min(430px,calc(100vw - 24px));max-height:min(420px,calc(100dvh - 32px));overflow:auto;padding:15px 18px;border:1px solid #cbdcd0;border-radius:10px;background:#fff;color:#25372e;box-shadow:0 10px 35px #183d302b;font:13px/1.6 system-ui,sans-serif;text-transform:none;letter-spacing:normal;white-space:normal;text-align:left}.fp-tooltip strong{display:block;margin-bottom:7px;color:#194731}.fp-tooltip-text{display:block;white-space:pre-wrap}.fp-tooltip ul{padding-left:18px;margin:8px 0 0}.fp-tooltip li{margin:5px 0;white-space:pre-wrap;overflow-wrap:anywhere}.fp .fp-line-note{white-space:nowrap;min-width:90px;max-width:none}.fp-notes-badge{padding:5px 9px;background:#fff5dd;color:#7c5716;border-radius:12px;font-size:12px;white-space:nowrap}.fp-live-status{display:flex;gap:12px;align-items:center;font-size:12px;color:#537660;max-width:480px}.fp-refresh-error{color:#a33e2d}.fp-chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.fp-chart-panel{min-width:0;border:1px solid #e1e9e3;border-radius:10px;padding:16px 10px 2px}.fp-chart-panel h3{margin:0 8px 8px}.fp-chart-scroll{overflow-x:auto}.fp-chart-scroll svg{width:100%;display:block;max-height:310px}.fp-chart-axis{font:11px system-ui,sans-serif;fill:#63786b}.fp-chart-legend{display:flex;gap:20px;flex-